import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The services' own marks, for telling them apart at a glance: SoundCloud's cloud, YouTube
 * Music's ring, Yandex's "Я" (Yandex Music has no mark of its own in the set). Drawn from Simple
 * Icons (simpleicons.org, CC0), in one colour, so that they tint like any other icon.
 */
object ServiceIcons {
    val SoundCloud: ImageVector by lazy { icon("SoundCloud", SOUNDCLOUD) }
    val YouTubeMusic: ImageVector by lazy { icon("YouTube Music", YOUTUBE_MUSIC) }
    val Yandex: ImageVector by lazy { icon("Yandex", YANDEX) }

    private fun icon(name: String, path: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f
        ).addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black)).build()

